18	package org.apache.kafka.shell.command;
19	
20	import org.apache.kafka.image.node.MetadataNode;
21	import org.apache.kafka.shell.InteractiveShell;
22	import org.apache.kafka.shell.glob.GlobVisitor;
23	import org.apache.kafka.shell.glob.GlobVisitor.MetadataNodeInfo;
24	import org.apache.kafka.shell.state.MetadataShellState;
25	
26	import net.sourceforge.argparse4j.inf.ArgumentParser;
27	import net.sourceforge.argparse4j.inf.Namespace;
28	
29	import org.jline.reader.Candidate;
30	import org.slf4j.Logger;
31	import org.slf4j.LoggerFactory;
32	
33	import java.io.PrintWriter;
34	import java.util.ArrayList;
35	import java.util.Arrays;
36	import java.util.List;
37	import java.util.Objects;
38	import java.util.Optional;
39	import java.util.OptionalInt;
40	
41	/**
42	 * Implements the ls command.
43	 */
44	public final class LsCommandHandler implements Commands.Handler {
45	    private static final Logger log = LoggerFactory.getLogger(LsCommandHandler.class);
46	
47	    public static final Commands.Type TYPE = new LsCommandType();
48	
49	    public static class LsCommandType implements Commands.Type {
50	        private LsCommandType() {
51	        }
52	
53	        @Override
54	        public String name() {
55	            return "ls";
56	        }
57	
58	        @Override
59	        public String description() {
60	            return "List metadata nodes.";
61	        }
62	
63	        @Override
64	        public boolean shellOnly() {
65	            return false;
66	        }
67	
68	        @Override
69	        public void addArguments(ArgumentParser parser) {
70	            parser.addArgument("targets").
71	                nargs("*").
72	                help("The metadata node paths to list.");
73	        }
74	
75	        @Override
76	        public Commands.Handler createHandler(Namespace namespace) {
77	            return new LsCommandHandler(namespace.getList("targets"));
78	        }
79	
80	        @Override
81	        public void completeNext(
82	            MetadataShellState state,
83	            List<String> nextWords,
84	            List<Candidate> candidates
85	        ) throws Exception {
86	            CommandUtils.completePath(state, nextWords.get(nextWords.size() - 1), candidates);
87	        }
88	    }
89	
90	    private final List<String> targets;
91	
92	    public LsCommandHandler(List<String> targets) {
93	        this.targets = targets;
94	    }
95	
96	    static class TargetDirectory {
97	        private final String name;
98	        private final List<String> children;
99	
100	        TargetDirectory(String name, List<String> children) {
101	            this.name = name;
102	            this.children = children;
103	        }
104	    }
105	
106	    @Override
107	    public void run(
108	        Optional<InteractiveShell> shell,
109	        PrintWriter writer,
110	        MetadataShellState state
111	    ) throws Exception {
112	        List<String> targetFiles = new ArrayList<>();
113	        List<TargetDirectory> targetDirectories = new ArrayList<>();
114	        for (String target : CommandUtils.getEffectivePaths(targets)) {
115	            state.visit(new GlobVisitor(target, entryOption -> {
116	                if (entryOption.isPresent()) {
117	                    MetadataNodeInfo info = entryOption.get();
118	                    MetadataNode node = info.node();
119	                    if (node.isDirectory()) {
120	                        List<String> children = new ArrayList<>(node.childNames());
121	                        children.sort(String::compareTo);
122	                        targetDirectories.add(
123	                            new TargetDirectory(info.lastPathComponent(), children));
124	                    } else {
125	                        targetFiles.add(info.lastPathComponent());
126	                    }
127	                } else {
128	                    writer.println("ls: " + target + ": no such file or directory.");
129	                }
130	            }));
131	        }
132	        OptionalInt screenWidth = shell.map(interactiveShell -> OptionalInt.of(interactiveShell.screenWidth())).orElseGet(OptionalInt::empty);
133	        log.trace("LS : targetFiles = {}, targetDirectories = {}, screenWidth = {}",
134	            targetFiles, targetDirectories, screenWidth);
135	        printTargets(writer, screenWidth, targetFiles, targetDirectories);
136	    }
137	
138	    static void printTargets(PrintWriter writer,
139	                             OptionalInt screenWidth,
140	                             List<String> targetFiles,
141	                             List<TargetDirectory> targetDirectories) {
142	        printEntries(writer, "", screenWidth, targetFiles);
143	        boolean needIntro = !targetFiles.isEmpty() || targetDirectories.size() > 1;
144	        boolean firstIntro = targetFiles.isEmpty();
145	        for (TargetDirectory targetDirectory : targetDirectories) {
146	            String intro = "";
147	            if (needIntro) {
148	                if (!firstIntro) {
149	                    intro = intro + String.format("%n");
150	                }
151	                intro = intro + targetDirectory.name + ":";
152	                firstIntro = false;
153	            }
154	            log.trace("LS : targetDirectory name = {}, children = {}",
155	                targetDirectory.name, targetDirectory.children);
156	            printEntries(writer, intro, screenWidth, targetDirectory.children);
157	        }
158	    }
159	
160	    static void printEntries(PrintWriter writer,
161	                             String intro,
162	                             OptionalInt screenWidth,
163	                             List<String> entries) {
164	        if (entries.isEmpty()) {
165	            return;
166	        }
167	        if (!intro.isEmpty()) {
168	            writer.println(intro);
169	        }
170	        ColumnSchema columnSchema = calculateColumnSchema(screenWidth, entries);
171	        int numColumns = columnSchema.numColumns();
172	        int numLines = (entries.size() + numColumns - 1) / numColumns;
173	        for (int line = 0; line < numLines; line++) {
174	            StringBuilder output = new StringBuilder();
175	            for (int column = 0; column < numColumns; column++) {
176	                int entryIndex = line + (column * columnSchema.entriesPerColumn());
177	                if (entryIndex < entries.size()) {
178	                    String entry = entries.get(entryIndex);
179	                    output.append(entry);
180	                    if (column < numColumns - 1) {
181	                        int width = columnSchema.columnWidth(column);
182	                        for (int i = 0; i < width - entry.length(); i++) {
183	                            output.append(" ");
184	                        }
185	                    }
186	                }
187	            }
188	            writer.println(output);
189	        }
190	    }
191	
192	    static ColumnSchema calculateColumnSchema(OptionalInt screenWidth,
193	                                              List<String> entries) {
194	        if (screenWidth.isEmpty()) {
195	            return new ColumnSchema(1, entries.size());
196	        }
197	        int maxColumns = screenWidth.getAsInt() / 4;
198	        if (maxColumns <= 1) {
199	            return new ColumnSchema(1, entries.size());
200	        }
201	        ColumnSchema[] schemas = new ColumnSchema[maxColumns];
202	        for (int numColumns = 1; numColumns <= maxColumns; numColumns++) {
203	            schemas[numColumns - 1] = new ColumnSchema(numColumns,
204	                (entries.size() + numColumns - 1) / numColumns);
205	        }
206	        for (int i = 0; i < entries.size(); i++) {
207	            String entry = entries.get(i);
208	            for (ColumnSchema schema : schemas) {
209	                schema.process(i, entry);
210	            }
211	        }
212	        for (int s = schemas.length - 1; s > 0; s--) {
213	            ColumnSchema schema = schemas[s];
214	            if (schema.columnWidths[schema.columnWidths.length - 1] != 0 &&
215	                    schema.totalWidth() <= screenWidth.getAsInt()) {
216	                return schema;
217	            }
218	        }
219	        return schemas[0];
220	    }
221	
222	    static class ColumnSchema {
223	        private final int[] columnWidths;
224	        private final int entriesPerColumn;
225	
226	        ColumnSchema(int numColumns, int entriesPerColumn) {
227	            this.columnWidths = new int[numColumns];
228	            this.entriesPerColumn = entriesPerColumn;
229	        }
230	
231	        ColumnSchema setColumnWidths(Integer... widths) {
232	            for (int i = 0; i < widths.length; i++) {
233	                columnWidths[i] = widths[i];
234	            }
235	            return this;
236	        }
237	
238	        void process(int entryIndex, String output) {
239	            int columnIndex = entryIndex / entriesPerColumn;
240	            columnWidths[columnIndex] = Math.max(
241	                columnWidths[columnIndex], output.length() + 2);
242	        }
243	
244	        int totalWidth() {
245	            int total = 0;
246	            for (int columnWidth : columnWidths) {
247	                total += columnWidth;
248	            }
249	            return total;
250	        }
251	
252	        int numColumns() {
253	            return columnWidths.length;
254	        }
255	
256	        int columnWidth(int columnIndex) {
257	            return columnWidths[columnIndex];
258	        }
259	
260	        int entriesPerColumn() {
261	            return entriesPerColumn;
262	        }
263	
264	        @Override
265	        public int hashCode() {
266	            return Objects.hash(Arrays.hashCode(columnWidths), entriesPerColumn);
267	        }
268	
269	        @Override
270	        public boolean equals(Object o) {
271	            if (!(o instanceof ColumnSchema other)) return false;
272	            if (entriesPerColumn != other.entriesPerColumn) return false;
273	            return Arrays.equals(columnWidths, other.columnWidths);
274	        }
275	
276	        @Override
277	        public String toString() {
278	            StringBuilder bld = new StringBuilder("ColumnSchema(columnWidths=[");
279	            String prefix = "";
280	            for (int columnWidth : columnWidths) {
281	                bld.append(prefix);
282	                bld.append(columnWidth);
283	                prefix = ", ";
284	            }
285	            bld.append("], entriesPerColumn=").append(entriesPerColumn).append(")");
286	            return bld.toString();
287	        }
288	    }
289	
290	    @Override
291	    public int hashCode() {
292	        return Objects.hashCode(targets);
293	    }
294	
295	    @Override
296	    public boolean equals(Object other) {
297	        if (!(other instanceof LsCommandHandler o)) return false;
298	        return Objects.equals(o.targets, targets);
299	    }
300	}
