17	
18	package org.apache.kafka.shell.command;
19	
20	import org.apache.kafka.image.node.MetadataNode;
21	import org.apache.kafka.shell.state.MetadataShellState;
22	
23	import org.jline.reader.Candidate;
24	
25	import java.util.ArrayList;
26	import java.util.List;
27	import java.util.TreeSet;
28	
29	/**
30	 * Utility functions for command handlers.
31	 */
32	public final class CommandUtils {
33	    /**
34	     * Convert a list of paths into the effective list of paths which should be used.
35	     * Empty strings will be removed.  If no paths are given, the current working
36	     * directory will be used.
37	     *
38	     * @param paths     The input paths.  Non-null.
39	     *
40	     * @return          The output paths.
41	     */
42	    public static List<String> getEffectivePaths(List<String> paths) {
43	        List<String> effectivePaths = new ArrayList<>();
44	        for (String path : paths) {
45	            if (!path.isEmpty()) {
46	                effectivePaths.add(path);
47	            }
48	        }
49	        if (effectivePaths.isEmpty()) {
50	            effectivePaths.add(".");
51	        }
52	        return effectivePaths;
53	    }
54	
55	    /**
56	     * Generate a list of potential completions for a prefix of a command name.
57	     *
58	     * @param commandPrefix     The command prefix.  Non-null.
59	     * @param candidates        The list to add the output completions to.
60	     */
61	    public static void completeCommand(String commandPrefix, List<Candidate> candidates) {
62	        String command = Commands.TYPES.ceilingKey(commandPrefix);
63	        while (command != null && command.startsWith(commandPrefix)) {
64	            candidates.add(new Candidate(command));
65	            command = Commands.TYPES.higherKey(command);
66	        }
67	    }
68	
69	    /**
70	     * Convert a path to a list of path components.
71	     * Multiple slashes in a row are treated the same as a single slash.
72	     * Trailing slashes are ignored.
73	     */
74	    public static List<String> splitPath(String path) {
75	        List<String> results = new ArrayList<>();
76	        String[] components = path.split("/");
77	        for (String component : components) {
78	            if (!component.isEmpty()) {
79	                results.add(component);
80	            }
81	        }
82	        return results;
83	    }
84	
85	    public static List<String> stripDotPathComponents(List<String> input) {
86	        List<String> output = new ArrayList<>();
87	        for (String string : input) {
88	            if (string.equals("..")) {
89	                if (!output.isEmpty()) {
90	                    output.remove(output.size() - 1);
91	                }
92	            } else if (!string.equals(".")) {
93	                output.add(string);
94	            }
95	        }
96	        return output;
97	    }
98	
99	    /**
100	     * Generate a list of potential completions for a path.
101	     *
102	     * @param state             The MetadataShellState.
103	     * @param pathPrefix        The path prefix.  Non-null.
104	     * @param candidates        The list to add the output completions to.
105	     */
106	    public static void completePath(
107	        MetadataShellState state,
108	        String pathPrefix,
109	        List<Candidate> candidates
110	    ) {
111	        state.visit(data -> {
112	            String absolutePath = pathPrefix.startsWith("/") ?
113	                pathPrefix : data.workingDirectory() + "/" + pathPrefix;
114	            List<String> pathComponents = stripDotPathComponents(splitPath(absolutePath));
115	            MetadataNode directory = data.root();
116	            int numDirectories = pathPrefix.endsWith("/") ?
117	                pathComponents.size() : pathComponents.size() - 1;
118	            for (int i = 0; i < numDirectories; i++) {
119	                MetadataNode node = directory.child(pathComponents.get(i));
120	                if (node == null || !node.isDirectory()) {
121	                    return;
122	                }
123	                directory = node;
124	            }
125	            String lastComponent = "";
126	            if (numDirectories >= 0 && numDirectories < pathComponents.size()) {
127	                lastComponent = pathComponents.get(numDirectories);
128	            }
129	            TreeSet<String> children = new TreeSet<>(directory.childNames());
130	            String candidate = children.ceiling(lastComponent);
131	            String effectivePrefix;
132	            int lastSlash = pathPrefix.lastIndexOf('/');
133	            if (lastSlash < 0) {
134	                effectivePrefix = "";
135	            } else {
136	                effectivePrefix = pathPrefix.substring(0, lastSlash + 1);
137	            }
138	            while (candidate != null && candidate.startsWith(lastComponent)) {
139	                StringBuilder candidateBuilder = new StringBuilder();
140	                candidateBuilder.append(effectivePrefix).append(candidate);
141	                boolean complete = true;
142	                MetadataNode child = directory.child(candidate);
143	                if (child != null && child.isDirectory()) {
144	                    candidateBuilder.append("/");
145	                    complete = false;
146	                }
147	                candidates.add(new Candidate(candidateBuilder.toString(),
148	                    candidateBuilder.toString(), null, null, null, null, complete));
