    54	     * Throws an exception if the glob is malformed.
    55	     */
    56	    static String toRegularExpression(String glob) {
    57	        StringBuilder output = new StringBuilder("^");
    58	        boolean literal = true;
    59	        boolean processingGroup = false;
    60	
    61	        for (int i = 0; i < glob.length(); ) {
    62	            char c = glob.charAt(i++);
    63	            switch (c) {
    64	                case '?':
    65	                    literal = false;
    66	                    output.append(".");
    67	                    break;
    68	                case '*':
    69	                    literal = false;
    70	                    output.append(".*");
    71	                    break;
    72	                case '\\':
    73	                    if (i == glob.length()) {
    74	                        output.append(c);
    75	                    } else {
    76	                        char next = glob.charAt(i);
    77	                        i++;
    78	                        if (isGlobSpecialCharacter(next) ||
    79	                                isRegularExpressionSpecialCharacter(next)) {
    80	                            output.append('\\');
