import org.apache.kafka.common.protocol.ApiMessage;
import org.apache.kafka.coordinator.group.GroupCoordinatorRecordSerde;
import org.apache.kafka.coordinator.group.generated.CoordinatorRecordJsonConverters;
import org.apache.kafka.coordinator.group.generated.CoordinatorRecordType;

import com.fasterxml.jackson.databind.JsonNode;

import java.util.Set;

/**
 * Formatter for use with tools such as console consumer: Consumer should also set exclude.internal.topics to false.
 * Formats the records on the __consumer_offsets topic which pertain to consumer groups using the consumer protocol.
 */
public class ConsumerGroupMessageFormatter extends CoordinatorRecordMessageFormatter {
    private static final Set<Short> ALLOWED_RECORDS = Set.of(
        CoordinatorRecordType.CONSUMER_GROUP_METADATA.id(),
        CoordinatorRecordType.CONSUMER_GROUP_PARTITION_METADATA.id(),
        CoordinatorRecordType.CONSUMER_GROUP_MEMBER_METADATA.id(),
        CoordinatorRecordType.CONSUMER_GROUP_TARGET_ASSIGNMENT_METADATA.id(),
        CoordinatorRecordType.CONSUMER_GROUP_TARGET_ASSIGNMENT_MEMBER.id(),
        CoordinatorRecordType.CONSUMER_GROUP_CURRENT_MEMBER_ASSIGNMENT.id(),
        CoordinatorRecordType.CONSUMER_GROUP_REGULAR_EXPRESSION.id()
    );

    public ConsumerGroupMessageFormatter() {
        super(new GroupCoordinatorRecordSerde());
    }

    @Override
    protected boolean isRecordTypeAllowed(short recordType) {
        return ALLOWED_RECORDS.contains(recordType);
    }

    @Override
    protected JsonNode keyAsJson(ApiMessage message) {
        return CoordinatorRecordJsonConverters.writeRecordKeyAsJson(message);
    }

    @Override
    protected JsonNode valueAsJson(ApiMessage message, short version) {
        return CoordinatorRecordJsonConverters.writeRecordValueAsJson(message, version);
    }
}
